import"./chunk-2NFLSA4Y.js";var i={electromagnet:{theory:{concept:"[[An electromagnet is a coil of wire, usually wound on an iron core, that becomes a magnet while an electric current flows through it.]]"},section:{coil:{title:"A current makes a field",text:"Each turn adds to the field inside the coil. A compass or field probe can detect it even though the field itself is invisible."},polarity:{title:"Turn it around",text:"The right-hand rule gives the field direction along the coil axis. Reversing the current reverses the field and swaps the north and south ends. With no current, this ideal coil has no field."},turns:{title:"Current and turns",text:"[[More current or more turns make a stronger field.]] A longer coil spreads the same turns out and weakens the central field."},core:{title:"Iron core",text:"[[An iron core can concentrate and greatly strengthen the field.]] This model uses one illustrative multiplier; real iron depends on its material, history and saturation."},probe:{title:"Measure along the axis",text:"Move the probe along the coil axis. The field is strongest near the middle and weaker farther away. The displayed formula describes this axial field only."}},param:{current:"Selected current",turns:"Number of turns",core:"Iron core",probe:"Probe position",length:"Coil length",radius:"Coil radius",timeStep:"Simulation timestep"},hint:{current:"Negative current reverses the magnetic poles; zero switches the electromagnet off.",turns:"More turns add to the magnetic field.",core:"A simplified iron core multiplies the field by eight.",probe:"Distance along the coil axis from its centre.",length:"The same turns spread over a longer coil.",radius:"The radius of each winding."},preset:{reverse:"Reverse",off:"Off",normal:"1 A",strong:"2 A"},measure:{strength:"Field strength at probe",current:"Actual current",field:"Signed axial field",target:"Field at selected current",centre:"Field at centre",coreFactor:"Effective core factor"},view:{vectors:"Field direction arrows",north:"N",south:"S",coil:"Coil \xB7 {turns} turns",core:"Iron core",probeReading:"Probe B = {value}",reading:"B at probe = {value}"},graph:{field:"Axial field over time"},formula:{long:"Approximation for a long solenoid",finite:"Field on the axis of a finite solenoid"},assumption:{thin:"The coil is evenly wound and thin; wire resistance, heating and induction are omitted.",core:"The iron core has one fixed effective factor of eight. Saturation, hysteresis and remaining magnetisation after switching off are omitted.",ramp:"Press Play to let the supply current approach its selected value. The moving dots show charge direction schematically; their speed is not an electron drift speed. No electrical circuit is solved.",axis:"Only the field along the coil axis is calculated; arrows outside that axis are not predicted.",scale:"The 3D coil has an illustrative winding count; size and spacing are schematic. The core is shown as a transparent cutaway. The probe icon is below its sampled point on the axis so it stays visible. Orbit the camera to inspect the winding and conventional-current direction."},challenge:{strong:{title:"Strengthen the coil",description:"Make the selected field exceed 2500 \xB5T without an iron core.",hint:"Increase the number of turns or current."},reverse:{title:"Swap the poles",description:"Make the selected axial field less than \u22121000 \xB5T.",hint:"Choose a negative current."},off:{title:"Switch it off",description:"Set the selected field to zero.",hint:"Choose zero current."},core:{title:"Add an iron core",description:"Use a core to make the selected field exceed 10,000 \xB5T.",hint:"Switch on the core near the coil centre."},far:{title:"Move away",description:"Place the probe at least 0.15 m from the centre where the field is much weaker.",hint:"Move the probe along the axis and compare with the centre reading."}}}},r={sim:i};export{r as default,i as sim};
